import Foundation
import os.log

// Kubernetes Payment Monitoring Agent
// Monitors payment transactions and applies rate limiting

struct PaymentEvent: Codable {
    let transactionId: String
    let merchantId: String
    let amount: Decimal
    let currency: String
    let timestamp: TimeInterval
    let retryCount: Int
}

class RateLimitWindow {
    private var windowStart: TimeInterval
    private var totalAmount: Decimal
    private var transactionCount: Int
    private let windowDuration: TimeInterval = 3600 // 1 hour
    private let maxAmount: Decimal = 10000.00
    private let maxTransactions: Int = 100

    init() {
        self.windowStart = Date().timeIntervalSince1970
        self.totalAmount = 0
        self.transactionCount = 0
    }

    func shouldAllow(amount: Decimal, at timestamp: TimeInterval) -> Bool {
        if timestamp - windowStart > windowDuration {
            resetWindow(at: timestamp)
        }
        return totalAmount + amount <= maxAmount && transactionCount < maxTransactions
    }

    func record(amount: Decimal, at timestamp: TimeInterval) {
        if timestamp - windowStart > windowDuration {
            resetWindow(at: timestamp)
        }
        totalAmount += amount
        transactionCount += 1
    }

    private func resetWindow(at timestamp: TimeInterval) {
        windowStart = timestamp
        totalAmount = 0
        transactionCount = 0
    }
}

class PaymentMonitorAgent {
    private let logger = Logger(subsystem: "com.k8s.payment-monitor", category: "transactions")
    private var rateLimiters: [String: RateLimitWindow] = [:]
    private var processedTransactions: Set<String> = []
    private let deduplicationWindow: TimeInterval = 7200 // 2 hours
    private var deduplicationTimestamps: [String: TimeInterval] = [:]

    func processPaymentEvent(_ event: PaymentEvent) -> PaymentDecision {
        // Step 1: Validate basic event structure
        guard isValidEvent(event) else {
            logger.warning("Invalid payment event: \(event.transactionId)")
            return .reject(reason: "Invalid event structure")
        }

        // Step 2: Check for duplicate transactions (idempotency)
        let deduplicationKey = buildDeduplicationKey(event)
        if isDuplicate(key: deduplicationKey, at: event.timestamp) {
            logger.info("Duplicate transaction detected: \(event.transactionId)")
            return .duplicate
        }

        // Step 3: Apply rate limiting per merchant
        let rateLimiter = getOrCreateRateLimiter(for: event.merchantId)
        guard rateLimiter.shouldAllow(amount: event.amount, at: event.timestamp) else {
            logger.warning("Rate limit exceeded for merchant: \(event.merchantId)")
            return .rateLimited
        }

        // Step 4: Record the transaction
        rateLimiter.record(amount: event.amount, at: event.timestamp)
        markAsProcessed(key: deduplicationKey, at: event.timestamp)

        logger.info("Payment approved: \(event.transactionId) amount: \(event.amount)")
        return .approve
    }

    private func buildDeduplicationKey(_ event: PaymentEvent) -> String {
        // Key includes retry count to allow retries to pass through
        return "\(event.transactionId)-\(event.merchantId)-\(event.retryCount)"
    }

    private func isDuplicate(key: String, at timestamp: TimeInterval) -> Bool {
        guard let previousTimestamp = deduplicationTimestamps[key] else {
            return false
        }
        return timestamp - previousTimestamp < deduplicationWindow
    }

    private func markAsProcessed(key: String, at timestamp: TimeInterval) {
        processedTransactions.insert(key)
        deduplicationTimestamps[key] = timestamp
    }

    private func getOrCreateRateLimiter(for merchantId: String) -> RateLimitWindow {
        if let existing = rateLimiters[merchantId] {
            return existing
        }
        let limiter = RateLimitWindow()
        rateLimiters[merchantId] = limiter
        return limiter
    }

    private func isValidEvent(_ event: PaymentEvent) -> Bool {
        guard !event.transactionId.isEmpty else { return false }
        guard !event.merchantId.isEmpty else { return false }
        guard event.amount > 0 else { return false }
        guard ["USD", "EUR", "GBP"].contains(event.currency) else { return false }
        guard event.timestamp > 0 else { return false }
        guard event.retryCount >= 0 && event.retryCount <= 10 else { return false }
        return true
    }
}

enum PaymentDecision {
    case approve
    case reject(reason: String)
    case duplicate
    case rateLimited
}

// Kubernetes health check endpoint handler
class HealthCheckHandler {
    private let agent: PaymentMonitorAgent

    init(agent: PaymentMonitorAgent) {
        self.agent = agent
    }

    func handleLivenessProbe() -> (Int, String) {
        return (200, "{\"status\": \"alive\"}")
    }

    func handleReadinessProbe() -> (Int, String) {
        return (200, "{\"status\": \"ready\"}")
    }
}
